#!/usr/bin/env sh
# fetch Trufi~Cochabamba~Bolivia (XX) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://github.com/trufi-association/trufi-gtfs-builder/raw/refs/heads/main/examples/Bolivia-Cochabamba/out/cochabamba.gtfs.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
